// Help's Module Guide entries for Crest IMS, in a chunk of their own (PERF-9, S876): Help.js used to
// carry all five module lists, so /help downloaded ~538 KB before its first tab could paint.
// loadHelpFeatures.js fetches this file with the other four. A new IMS page's Help entry goes here.
import { groupImsFeatures } from './helpFeatureTiers'

